<script src="https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js"></script>
<script>
(function(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  function initMarquee2(){
    var track = document.getElementById('marquee-track2');
    if(!track) return;
    var total = track.scrollWidth / 4;
    gsap.set(track,{x:0});
    gsap.to(track,{
      x: -total,
      duration: 30,
      ease: "none",
      repeat: -1,
      modifiers: {
        x: gsap.utils.unitize(function(x){ return parseFloat(x) % total; })
      }
    });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', initMarquee2); } else { setTimeout(initMarquee2, 80); }
})();
</script>
